+public class M4AChapterReaderTest {
+
+    @Test
+    public void testFiles() throws IOException {
+        testFile();
+    }
+
+    public void testFile() throws IOException {
+        InputStream inputStream = getClass().getClassLoader()
+                .getResource("nero-chapters.m4a").openStream();
